import ast
import inspect

import solution
from solution import fib4

import pytest
from hypothesis import given
import hypothesis.strategies as st


def ref_fib4(n: int) -> int:
    a = [0, 0, 2, 0]
    if n < 4:
        return a[n]
    for _ in range(4, n + 1):
        a.append(a[-1] + a[-2] + a[-3] + a[-4])
    return a[n]


def test_spec_example_5():
    assert fib4(5) == 4


def test_spec_example_6():
    assert fib4(6) == 8


def test_spec_example_7():
    assert fib4(7) == 14


def test_base_cases():
    assert fib4(0) == 0
    assert fib4(1) == 0
    assert fib4(2) == 2
    assert fib4(3) == 0


def test_first_eight_values():
    assert [fib4(i) for i in range(8)] == [0, 0, 2, 0, 2, 4, 8, 14]


@given(st.integers(min_value=4, max_value=18))
def test_recurrence_relation(n):
    assert fib4(n) == fib4(n - 1) + fib4(n - 2) + fib4(n - 3) + fib4(n - 4)


@given(st.integers(min_value=0, max_value=18))
def test_matches_iterative_reference_model(n):
    assert fib4(n) == ref_fib4(n)


@given(st.integers(min_value=0, max_value=18))
def test_result_is_int(n):
    r = fib4(n)
    assert type(r) == int


def test_no_recursion_dynamic_reentry():
    # Spec requires: "Do not use recursion." A recursive fib4 re-enters
    # the global `fib4` many times even for small n. An iterative
    # implementation calls it exactly once.
    orig = solution.fib4
    calls = []

    def counting_wrapper(n):
        calls.append(n)
        return orig(n)

    solution.fib4 = counting_wrapper
    try:
        # re-fetch global used inside solution.fib4: it looks up
        # solution.fib4, so recursive calls go through the wrapper
        result = solution.fib4(5)
    finally:
        solution.fib4 = orig
    assert result == 4
    assert len(calls) == 1, f"fib4 re-entered itself {len(calls)} times (recursion forbidden)"


def test_no_self_call_static():
    # Static enforcement of "Do not use recursion": the function body
    # must not call `fib4` again.
    src = inspect.getsource(solution.fib4)
    tree = ast.parse(src)
    func_def = next(
        node for node in ast.walk(tree) if isinstance(node, ast.FunctionDef)
    )
    for node in ast.walk(func_def):
        if isinstance(node, ast.Call):
            f = node.func
            if isinstance(f, ast.Name) and f.id == "fib4":
                pytest.fail("fib4 implementation calls itself recursively")
            if isinstance(f, ast.Attribute) and f.attr == "fib4":
                pytest.fail("fib4 implementation calls itself recursively")
